"""Le plateau de l'histoire (63 cases, façon jeu de l'oie) et la frise chronologique.

Chaque case est aussi un événement de la frise : les deux partagent les mêmes données.
D'autres dates de la frise se débloquent en maîtrisant des compétences.
"""

EPOQUES = [
    ("antiquite", "Des origines à l'Antiquité", None, 475),
    ("moyen-age", "Moyen Âge", 476, 1449),
    ("renaissance", "Renaissance", 1450, 1599),
    ("classique", "Âge classique et Lumières", 1600, 1799),
    ("xixe", "XIXe siècle", 1800, 1899),
    ("xxe", "XXe et XXIe siècles", 1900, None),
]
PICTO_EPOQUE = {"antiquite": "amphore", "moyen-age": "enluminure", "renaissance": "plume", "classique": "bougie", "xixe": "engrenage", "xxe": "atome"}


def epoque(annee):
    for id, _, debut, fin in EPOQUES:
        if (debut is None or annee >= debut) and (fin is None or annee <= fin):
            return id
    raise ValueError(annee)


