from aides import anecdote, citation, succes  # noqa: E402


def numero(id):
    return next(i + 1 for i, c in enumerate(CASES) if c[0] == id)


def debut_epoque(ep):
    return next(i + 1 for i, c in enumerate(CASES) if epoque(c[1]) == ep)


def atteinte(n):
    # v15 : une époque est atteinte dès qu'on s'arrête sur une de ses cases, ou plus loin.
    return {"type": "epoque_atteinte", "n": n}


def visitee(n):
    return {"type": "case_visitee", "n": n}


